(()=>{function setRole(){if(!window.dashboard?.company)return;const roles=dashboard.company.capabilities||[],label=roles.includes('contractor')&&roles.includes('subcontractor')?'Contractor & Subcontractor':roles.includes('contractor')?'Contractor':roles.includes('subcontractor')?'Subcontractor':'Company';const badge=document.getElementById('navRole');if(badge)badge.textContent=label}setRole();const timer=setInterval(()=>{setRole();if(window.dashboard?.company)clearInterval(timer)},100);setTimeout(()=>clearInterval(timer),15000);new MutationObserver(setRole).observe(document.getElementById('navRole'),{childList:true})})();
